Our noise model in the analysis is as follows: 
We assume that we are given a finite set of samples $\{r_i\}_{i=1}^n$ drawn independently from 
\begin{equation}\label{eq:Msigma}
	\mathcal{M}_\sigma \stackrel{\bigtriangleup}{=} \{q\in \mathbb{R}^D ~|~ dist(q, \mathcal{M}) < \sigma \}
	,\end{equation}
a tubular neighborhood of $\mathcal{M}$.

we define the graph of $\phi_p$ to be
\begin{equation}\label{eq:FunctionGraph_init}
	\Gamma_{\phi_p, W_p} \stackrel{\bigtriangleup}{=} \{p + (x, \phi_p(x))_{T_p\mathcal{M}} | x\in W_{T_p\mathcal{M}} \}  
	.

Given a point $r\in\mathcal{M}_\sigma$ we limit the the region of interest (ROI) to:
\begin{equation}\label{eq:ROI_clean}
	U_{\textrm{ROI}} = {\{r_i|\operatorname{dist}(r_i,r)<\sqrt{\sigma\tau}\}}
	,\end{equation}
and denote the number of samples in the ROI by $N$.

we define the relevant coordinate system as the pair $(q, H)\in \mathbb{R}^D\times Gr(d, D)$, which minimizes the functional:
\begin{equation}\label{eq:J1_clean}
	J_1(r; q, H) = \frac{1}{N}\sum_{r_i\in U_{\textrm{ROI}}} \operatorname{dist}^2 (r_i - q,H)
\end{equation}
under the constraints
\begin{enumerate}
	\item Orthogonality: $ r - q\perp H $.

Explicitly, we denote
\begin{equation}\label{eq:argmin1_clean}
	q^*(r), H^*(r) = \arg\!\min_{\substack{ q, H \\ r-q \perp H \\ \|r- q\|<2\sigma}} J_1(r; q, H)
\end{equation}

\begin{equation}\label{eq:argmin1_clean}
	q^*(r), H^*(r) = \arg\!\min_{\substack{ q, H \\ r-q \perp H \\ \|r- q\|<2\sigma}} J_1(r; q, H)
\end{equation}

	\caption{Step 1: Find an initial coordinate system}
	\label{alg:alg1_clean}
	\begin{algorithmic}[1]
		\Statex {\bfseries Input:}\begin{tabular}[t]{ll}
			$\{r_i\}_{i=1}^n\subset \mathcal{M}_\sigma$ & noisy samples of a $d$ dimensional manifold $ \mathcal{M} $.\\
			$r\in \mathcal{M}_\sigma$ & a point in a tubular neighborhood of $\mathcal{M}$.\\
            $d$ & The dimension of the manifold $\mathcal{M}$.\\
            $\tau$ & lower bound on the reach of $\mathcal{M}$. \\
            $\sigma$ & upper bound on the noise level.\\

		\end{tabular}
		\Statex {\bfseries Output:}\begin{tabular}[t]{ll}
			$q^*$ & crude estimation of $p = Proj_\mathcal{M}(r)$.\\
			$H^*$ & estimation of $T_p\mathcal{M}$.\\
		\end{tabular}
		\State Disregard points outside of $U_{\textrm{ROI}}$ (plugging $\tau_\text{bound}, \sigma_\text{bound}$ into Eq. \eqref{eq:ROI_clean}).
		\State Find $q^*, H^*$ minimizing \eqref{eq:argmin1_clean} subject to $\norm{q^* - r}<2\sigma$ and $r - q^* \perp H^*$. 
	\end{algorithmic}

Explicitly, the local polynomial regression is defined through
\begin{equation}\label{eq:argmin2_clean}
	\pi^*_{q, H} = \arg\!\min_{\pi\in \Pi_{k-1}^{d\mapsto D}} J_2(\pi ~|~ q, H)
	.\end{equation}

define
\begin{equation}\label{eq:pi_star_median_trick}
	\pi^*_{q, H} = \mbox{Algorithm 2 of \cite{aizenbud2021VectorEstimation}} (x_i,y_i),
\end{equation}
where $y_i$ are the projection of $r_i-q$ onto $H^\perp$.

That is, we define a local patch of the manifold through the graph 
\begin{equation}\label{eq:Graph_fl}
	\Gamma_{f_\ell, r, H_\ell} = \{r + (x, f_\ell(x))_{H_\ell} | x\in B_{H_\ell}(0,\rho) \}\subset\mathcal{M},   
\end{equation}
where $\rho$ is some radius where this function is defined (see Lemma \ref{lem:M_is_locally_a_fuinction_clean} for more details regarding the existence of such $\rho > 0$).

Following this, we define 
\begin{equation}\label{eq:fl_def}
	f_{\ell+1}:(r, H_{\ell+1}) \to H_{\ell+1} ^\perp \simeq \mathbb{R}^{D-d}    
\end{equation}

	\caption{Step 2: estimating the manifold from a good initial guess}
	\label{alg:step2_clean}
	\begin{algorithmic}[1]
		\State {\bfseries Input:}\begin{tabular}[t]{ll}
			$\{r_i\}_{i=1}^n\subset \mathcal{M}_\sigma$ & Noisy samples of a $d$ dimensional manifold $ \mathcal{M} $.\\
            $d$ & The dimension of the manifold $\mathcal{M}$.\\

			$r\in \mathcal{M}_\sigma$ & a point in the tubular neighborhood of $\mathcal{M}$\\

			$H_0$ & Initial approx. of the tangent

		\end{tabular}
		\State {\bfseries Output:}\begin{tabular}[t]{ll}
			$\hat p_n$ & Estimation of $Proj_{\mathcal{M}}(r)\in \mathcal{M}$ .\\
			$\widehat{T_{\hat p_n}\mathcal{M}}$ & Estimation of   $T_{Proj_{\mathcal{M}}(r)}\mathcal{M}$.\\
		\end{tabular}



		\For{$\ell=0$ to $\kappa-1$}
		\State Compute  $\pi^*_{r,H_{\ell}}$ through a version of linear least-squares minimization  \eqref{eq:pi_star_median_trick}.
		\State Compute $ \mathcal{D}_{\pi^*_{r,H_{\ell}}}[0] $ the differential of  $\pi^*_{r,H_{\ell}}$ in some basis at zero.
		\State $H_{\ell+1} = \mathrm{Im}(\mathcal{D}_{\pi^*_{r,H_{\ell}}}[0]) $ \Comment{this is the column space of $ \mathcal{D}_{\pi^*_{r,H_{\ell}}}[0] $}.


		\EndFor 
		\State $\hat p_n = r + (0, \pi^*_{r, H_{\kappa}}(0))^T$ 

		\State $\widehat{T_{\hat p_n}\mathcal{M}} = H_\kappa $
		\State\Return $\hat p_n$ and $\widehat{T_{\hat p_n}\mathcal{M}}$.
	\end{algorithmic}

\caption{Step 1: in practice}
\label{alg:step1Inpractice_clean}
\begin{algorithmic}[1]
\State {\bfseries Input:} $\lbrace r_i \rbrace_{i=1}^N, r, d, \tau, \sigma,\epsilon$
\State{\bfseries Output:}\begin{tabular}[t]{ll}
                         $q$ - an $n$ dimensional vector \\
                         $U$ - an $n\times d$ matrix whose columns are $\lbrace u_j \rbrace_{j=1}^d$ 
                         \end{tabular}
                         \Comment{$H = q + Span\lbrace u_j \rbrace_{j=1}^d$}
\State define $R$ to be an $n\times N$ matrix whose columns are $r_i$
\State initialize $U$ with the first $d$ principal components of the spatially weighted PCA \label{algstep:U_init_in_practice}
\State $q\leftarrow r$
\Repeat
    \State $q_{prev} = q$
    \State $\tilde{R} = (R - repmat(q,1,N))\cdot \Theta$ \Comment{where $\Theta$ is an indicator for points in $U_{\textrm{ROI}}$}
    \State $X_{N\times d} = \tilde{R}^T U$ \Comment{find the representation of $r_i$ in $Col(U)$}
    \State define $\tilde{X}_{N\times (d+1)} = \left[(1,...,1)^T, X\right]$
    \State solve $\tilde{X}^T\tilde{X}\alpha = \tilde{X}^T \tilde{R}^T$ for $\alpha \in M_{(d+1)\times n}$ \Comment{solving the LS minimization of $\tilde{X}\alpha \approx \tilde{R}^T$}
    \State $\tilde{q} = q + \alpha(1,:)^T$
    \State $Q, \hat{R} = qr(\alpha(2:end, :)^T)$ \Comment{where $qr$ denotes the QR decomposition}
    \State $U \leftarrow Q$
    \State $q = \tilde{q} + U U^T (r-\tilde{q})$
\Until {$\|q-q_{\text{prev}}\|<\epsilon$}
\end{algorithmic}

	\caption{Step 2: in practice}
	\label{alg:step2InPractice_clean}
	\begin{algorithmic}[1]
		\State {\bfseries Input:}\begin{tabular}[t]{ll}
            $\{r_i\}_{i=1}^n$& a set of points in $\mathcal{M}_\sigma$ \\
            $d$ & The dimension of the manifold $\mathcal{M}$.\\
            $q_{-1}$ & a crude approximation of $p_r = Proj_\mathcal{M}(r)$ \\ &(initialized with $q^*$ of \eqref{eq:argmin1_clean})\\

			$H_0$ & Initial approximation of $T_{p}\mathcal{M}$ s.t. $\angle_{\max}(H_0,T_{p}\mathcal{M}) < \alpha_0$ \\
            &(initialized with $H^*$ of \eqref{eq:argmin1_clean})\\

		\end{tabular}
		\State {\bfseries Output:}\begin{tabular}[t]{ll}
				$\hat p_n$ & Estimation of some $p\in\mathcal{M}$.\\
				$\widehat{T_{\hat p_n}\mathcal{M}}$ & Estimate of  $T_p\mathcal{M}$.\\
		\end{tabular}

		\State Compute $\pi^*_{q_{-1}, H_0}$
		\State $q_0 = q_{-1} + (0,\pi^*_{q_{-1}, H_0}(0))_{H_0}$ 
        \Repeat 
        \State Compute $\pi^*_{q_\ell,H_{\ell}}$ through the least-squares minimization of \eqref{eq:argmin2_clean}.
        \State Compute $\mathcal{D}_{\pi^*_{q_\ell,H_{\ell}}}[0]$.
        \State Set $H_{\ell + 1} = \mathrm{Im}(\mathcal{D}_{\pi^*_{q_\ell,H_{\ell}}}[0])$
        \State Set $q_{\ell+1} = q_\ell + (0, \pi^*_{q_\ell,H_{\ell}}(0))_{H_\ell}$
		\Until {$|q_{\ell} - q_{\ell +1}| \leq \epsilon$}
		\State \Return $\hat p_n = q_{\ell+1}$,  $\widehat{T_{\hat p_n}\mathcal{M}} = H_{\ell+1} $

	\end{algorithmic}

\label{thm:Step2}
	Assume that $M>C_\tau\sqrt{D\log D}$.  Denote $\mathbf{p} = Proj_\mathcal{M} (r)$ where r is the input point for Algorithm \ref{alg:step2_clean}.
	Let $(q, H)$ be an initial coordinate system for which $\norm{q - p}\leq 3 \sigma$ and $ \angle_{\max} (H, T_p\mathcal{M}) \leq \sqrt{c_{M}/M}$, where $p= Proj_\mathcal{M}(q) \in \mathcal{M}$.
	For any $\delta>0$ arbitrarily small, denote by $ \hat p_n, \widehat{T_{\hat p_n}\mathcal{M}} $ the estimates derived from Algorithm \ref{alg:step2_clean} initialized with $(q,H)$ with the number of iterations $\kappa$ specified in Lemma \ref{lem:comute_kappa}. Then, there is $ N_{\delta} $ such that for all $ n > N_{\delta}  $ we have 
	\begin{equation}\label{eq:thm3.3_p_dist_bound}
		dist(\hat p_n, \mathcal{M}) \leq \frac{C_1\ln\left(\frac{1}{\delta}\right)}{n^{r_0}}= \mathcal{O}(n^{-r_0}),
	\end{equation}
	\begin{equation}\label{eq:thm3.3_p_bound}
		\norm{\hat p_n - \mathbf{p}} \leq C_2\ln\left(\frac{1}{\delta}\right) \left(\frac{ n}{\ln\left(\ln(n) \right)^2}\right)^{-r_1} = \wtilde{\mathcal{O}}(n^{-r_1})  ,
	\end{equation}
	and 
	\begin{equation}\label{eq:thm3.3_tangent_ang}
		\angle_{\max}(\widehat{T_{\hat p_n}\mathcal{M}},T_{\mathbf p}\mathcal{M}) \leq C_3\ln\left(\frac{1}{\delta}\right) \left(\frac{ n}{\ln\left(\ln(n) \right)^2}\right)^{-r_1} = \wtilde{\mathcal{O}}(n^{-r_1})    
	\end{equation}
	with probability of at least $ 1 - \delta $, where $ r_0 = \frac{k}{2k +d}, r_1 = \frac{k-1}{2k +d} $, and $ C_1,C_2,C_3$ are constants independent of $d, \delta$.

\label{lem:J1pTp_clean}
	Let the sampling assumption of \ref{sec:SamplingAssumptions} hold, let ${p_r} = Proj_\mathcal{M}(r)$ be the orthogonal projection of $r$ onto $\mathcal{M}$, and let $ T_{p_r}\mathcal{M} $ be the tangent to $ \mathcal{M} $ at $ {p_r} $.
	Then, for $M$ (of Assumption \ref{assume:noise}) large enough
	\begin{equation}\label{eq:TangentScore_clean}
		J_1(r; {p_r}, T_{{p_r}}\mathcal{M}) \leq 50 \cdot \sigma^2 
	\end{equation}

\[
	\| \hat p_n - p_\kappa \| \leq 8\sigma D C_{d}^2 \ln\left(\frac{1}{\delta}\right)^2 n^{-2r_1}\left(\ln\left(\ln(n) \right)\right)^{4r_1} + c\ln\left(\frac{1}{\delta}\right)n^{-r_0}
	\]

\label{def:principal_angles_clean}
	Let $V$ be an inner product space. Given two sub-spaces $\mathcal{U}, \mathcal{W}$ of dimensions $dim(\mathcal{U})=k, dim(\mathcal{W}) = l$, where $k \leq l$ there exists a sequence of $k$ angles $0 \leq \beta_1 \leq \ldots \leq \beta_k \leq \pi/2$ called the principal angles and their corresponding principal pairs of vectors $(u_i, w_i)\in\mathcal{U}\times\mathcal{W}$ for $i=1,\ldots,k$ such that $\angle(u_i,w_i) = \beta_i$ are defined by: 
	\begin{equation*}
	\begin{array}{ll}
	    u_1, w_1 \stackrel{\bigtriangleup}{=} \arg\!\min\limits_{\substack{u\in\mathcal{U}, w\in\mathcal{W} \\ \norm{u}=\norm{w} =1}}\arccos\left(\abs{\langle u, w \rangle}\right), &
	    \beta_1 \stackrel{\bigtriangleup}{=} \angle(u_1, w_1)
	\end{array}    
	,\end{equation*}
	and for $i > 1$
	\begin{equation*}
	\begin{array}{ll}
	    u_i, w_i \stackrel{\bigtriangleup}{=} \arg\!\min\limits_{\substack{u\perp\mathcal{U}_{i-1}, w\perp\mathcal{W}_{i-1} \\ \norm{u}=\norm{w} =1}}\arccos\left(\abs{\langle u, w \rangle}\right), &
	    \beta_i \stackrel{\bigtriangleup}{=} \angle(u_i, w_i)
	\end{array}
	,\end{equation*}
    where $$\mathcal{U}_i \stackrel{\bigtriangleup}{=} Span\{u_j\}_{j=1}^i ~,~ \mathcal{W}_i \stackrel{\bigtriangleup}{=} Span\{w_j\}_{j=1}^i.$$

\begin{equation*}
	\begin{array}{ll}
	    u_1, w_1 \stackrel{\bigtriangleup}{=} \arg\!\min\limits_{\substack{u\in\mathcal{U}, w\in\mathcal{W} \\ \norm{u}=\norm{w} =1}}\arccos\left(\abs{\langle u, w \rangle}\right), &
	    \beta_1 \stackrel{\bigtriangleup}{=} \angle(u_1, w_1)
	\end{array}    
	,\end{equation*}

\begin{equation*}
	\begin{array}{ll}
	    u_i, w_i \stackrel{\bigtriangleup}{=} \arg\!\min\limits_{\substack{u\perp\mathcal{U}_{i-1}, w\perp\mathcal{W}_{i-1} \\ \norm{u}=\norm{w} =1}}\arccos\left(\abs{\langle u, w \rangle}\right), &
	    \beta_i \stackrel{\bigtriangleup}{=} \angle(u_i, w_i)
	\end{array}
	,\end{equation*}

In our case, we measure the distance between two subspaces by taking the maximal principal angle (maximal angle) , and denote it as
\begin{equation}\label{eq:TheAngleLinear_clean}
    \angle_{\max}(\mathcal{U},\mathcal{W}) \stackrel{\bigtriangleup}{=} \max_{1\leq i\leq d}\beta_i
.\end{equation}

\label{lem:reach_ball_no_intersect_clean}
   Let $\mathcal{M}$ be a sub-manifold of $\mathbb{R}^D$ with reach $\tau$ and let $p\in\mathcal{M}$.
   Then, any open $D$ dimensional ball of radius $\rho \leq \tau$ that is tangent to $\mathcal{M}$ at $p$ does not intersect $\mathcal{M}$.

\label{lem:f_bound_circle_no_func_clean}
Let $\mathcal{M}$ be a $d$-dimensional sub-manifold of $\mathbb{R}^D$ with reach $\tau$. For any $p \in \mathcal{M}$, let $T_{p}\mathcal{M}$ be the tangent of $\mathcal{M}$ at $p$.
    For any $x = p + x_T$, where $x_T\in T_p\mathcal{M}$, and $y\in (T_p\mathcal{M})^\perp$  such that $\|x_T\|\leq \tau$, $\|y\| \leq \tau/2$ and $(x + y)\in \mathcal{M}$, we have that 
    \[
    \norm{y} \leq \tau-\sqrt{\tau^2-\norm{x_T}^2}
    \]

 \label{lem:f_bound_circle_H_no_func_clean}

    Let $\mathcal{M}$ be a $d$-dimensional sub-manifold of $\mathbb{R}^D$ with reach $\tau$. For any $p \in \mathcal{M}$, let $T_{p}\mathcal{M}$ be the tangent of $\mathcal{M}$ at $p$ and let $ H\in Gr(d, D) $ such that $ \angle_{\max}(T_p\mathcal{M}, H) = \alpha \leq \pi/4 $.
    For any $x = p + x_H$, where $x_H\in H$, $\|x_H\|\leq c_{\pi/4}\tau$ for some constant $c_{\pi/4}$ , and $y\in H^\perp$  such that $\|x-p\|\leq \tau \cos \alpha$, $\|y\| \leq \tau/2$ and $(x + y)\in \mathcal{M}$, we have that 
	\[
	-\tau\cos\alpha+\sqrt{\tau^2-(\norm{x} - \tau\sin\alpha)^2} \leq \|y\| \leq \tau\cos\alpha-\sqrt{\tau^2-(\norm{x} + \tau\sin\alpha)^2}
	\]

