\frac{\int\limits_{S_{D-d-1}}\int\limits_0^{g(x,\theta)} \theta r r^{D-d-1} drd\theta}{\int\limits_{S_{D-d-1}}\int\limits_0^{g(x,\theta)} r^{D-d-1} drd\theta}  = 
\frac{(D-d)\int\limits_{S_{D-d-1}}\theta g(x,\theta)^{D-d+1} d\theta}{(D-d+1)\int\limits_{S_{D-d-1}}g(x,\theta)^{D-d} d\theta}     
,\end{equation*}
where $dr$ is the measure over the radial component, $r^{D-d-1}$ is the Jacobian introduced by the change of variables and $d\theta$ is the measure over the $(D-d-1)$-dimensional sphere.
For brevity we introduce the notation $\wtilde D = D - d$ and get
\begin{equation}\label{eq:f_tilde-f_integrals}
\wtilde{f}(x) - f(x) = 
\frac{\int\limits_{\mathbb{S}_{\wtilde D-1}}\int\limits_0^{g(x,\theta)} \theta r r^{\wtilde D-1} drd\theta}{\int\limits_{\mathbb{S}_{\wtilde D-1}}\int\limits_0^{g(x,\theta)} r^{\wtilde D-1} drd\theta}  = 
\frac{\wtilde D \int\limits_{\mathbb{S}_{\wtilde D-1}}\theta g(x,\theta)^{\wtilde D+1} d\theta}{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}     
.\end{equation}

Next, by taking the differential of that expression with respect to $x$ we have that 
\begin{multline*}
    \mathcal{D}_{\wtilde{f}}[x] - \mathcal{D}_f[x] =
\frac{\wtilde D}{(\wtilde D+1)}\left(
\frac{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}\theta g(x,\theta)^{\wtilde D} \nabla_x g^T d\theta}
{\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} \right.\\
-\left.
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}\theta g(x,\theta)^{\wtilde D+1} d\theta \int\limits_{\mathbb{S}_{\wtilde D-1}} g(x,\theta)^{\wtilde D-1}\nabla_x g^T d\theta}
{\left(\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta\right)^2}     
\right)
,\end{multline*}
where $\nabla_x g$ stands for the gradient of $g(\theta, x)$ with respect to the $x$ variables only.
As can be seen in the above equation there is a multiplicative factor of size $\approx (D - d)$ for both summends.
In order to deal with this obstacle we wish to utilize the fact that in high dimensions most of the volume of a sphere is concentrated near an equator.
Thus, we split the domain into two different regions that we will deal with separately (we will use this trick in few of the other proofs). 
In case $D-d$ is small, then the following computations can be done without splitting the domain into two regions (one near the equator and the the second being the remaining cap), and include the $D-d$ factor in the constant that will be cancelled by $M$.
Therefore, we assume without losing the generality of our claim that $D-d = \wtilde D > 3$.
For any direction/unit vector $\vec{z}\in S_{\wtilde D}$ denote $\vec{z}^T\theta = z$ and 
\begin{equation}\label{eq:Omegas_def}
    \begin{aligned}
    \Omega_1 &= \{\theta~|~0\leq |\vec{z}^T\theta| \leq \xi\}\\
    \Omega_2 &= \{\theta~|~|\vec{z}^T\theta| > \xi\}
    \end{aligned}
\end{equation}
For some $\xi$ to be chosen later. Using the above notation, we have 
\begin{multline}\label{eq:zDftilde}
    \vec{z}^T\cdot  (\mathcal{D}_{\wtilde{f}}[x] - \mathcal{D}_f[x] )=
\frac{\wtilde D}{(\wtilde D+1)}\left(
\underbrace{\frac{(\wtilde D+1)\int\limits_{\mathbb{S}_{\wtilde D-1}}z g(x,\theta)^{\wtilde D} \nabla_x g^T d\theta}
{\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}  }_{I} \right.  \\
-\left.
\underbrace{\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}z g(x,\theta)^{\wtilde D+1} d\theta \int\limits_{\mathbb{S}_{\wtilde D-1}} g(x,\theta)^{\wtilde D-1}\nabla_x g^T d\theta}
{\left(\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta\right)^2}}_{II}     
\right)
\end{multline}
First we treat part $(I)$ of Eq. \eqref{eq:zDftilde} by splitting the domain into $\Omega_1$ and $\Omega_2$ of Eq. \ref{eq:Omegas_def}.

\begin{align*}
    (I) &= \frac{(\wtilde D+1)\left(\int\limits_{\Omega_1}z g(x,\theta)^{\wtilde D} \nabla_x g^T d\theta + \int\limits_{\Omega_2}z g(x,\theta)^{\wtilde D} \nabla_x g^T d\theta \right) }
{\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} 
\end{align*}

From \ref{lem:g_bond_weak} we have that $0 < \sigma \leq g(0,\theta)\leq \sigma + 4\sigma\alpha^2$, and from Lemma \ref{lem:bound_nablag} we have $\|\nabla_x g(0,\theta)\|\leq c_1 \sigma \alpha/\tau$. Then,
\begin{align*}
\norm{(I)} &\leq \frac{(\wtilde D+1)\left(\xi\int\limits_{\Omega_1} g(x,\theta)^{\wtilde D} \|\nabla_x g^T\| d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D} \|\nabla_x g^T\| d\theta \right)}
{\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta} \\
&\leq  \frac{(\wtilde D+1)c_1 \sigma \alpha \left(\xi\int\limits_{\Omega_1} g(x,\theta)^{\wtilde D}  d\theta + \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D}  d\theta \right)}
{\tau\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}
\\
&\leq  \frac{\xi(\wtilde D+1)c_1 \sigma \alpha}{\tau} + \frac{(\wtilde D+1)c_1 \sigma \alpha \int\limits_{\Omega_2} g(x,\theta)^{\wtilde D}  d\theta }
{\tau\int\limits_{\mathbb{S}_{\wtilde D-1}}g(x,\theta)^{\wtilde D} d\theta}
\\
&\leq  \frac{\xi(\wtilde D+1)c_1 \sigma \alpha}{\tau} + \frac{(\wtilde D+1)c_1 \sigma \alpha ( \sigma + 4\sigma\alpha^2)^{\wtilde D}\int\limits_{\Omega_2}  d\theta }
{\tau \sigma^{\wtilde D}\int\limits_{\mathbb{S}_{\wtilde D-1}} d\theta}
\end{align*}

Furthermore, using the following concentration of measure inequality (see e.g. \cite{milman2009asymptotic,Venkatesan2012high})
\begin{equation}\label{eq:Omega3_to_ball_ratio}
\frac{\int\limits_{\Omega_2}  d\theta}{\int\limits_{\mathbb{S}_{\wtilde D-1}}  d\theta} \leq \frac{2}{\xi\sqrt{\wtilde D-2}}e^{-(\wtilde D - 2 )\xi^2/2}
,\end{equation}
we have that,
\begin{align*}
    \norm{(I)} 
&\leq  \frac{\xi(\wtilde D+1)c_1 \sigma\alpha}{\tau} + \frac{(\wtilde D+1)c_1 \sigma\alpha (1 + 4\alpha^2)^{\wtilde D} }
{\tau}\frac{2}{\xi\sqrt{\wtilde D-2}}e^{-(\wtilde D - 2 )\xi^2/2}
\\
&\leq  \frac{\xi(\wtilde D+1)c_1 \sigma\alpha}{\tau} + \frac{c_2 \sigma\alpha \sqrt{\wtilde D+1}( 1 + 4\alpha^2)^{\wtilde D} }
{\tau}\frac{2}{\xi}e^{-(\wtilde D - 2 )\xi^2/2}
,\end{align*}
where $c_2 = 4c_1 \geq \frac{\sqrt{\wtilde D +1}}{\sqrt{\wtilde D - 2}} c_1$.

Since $M = \frac{\tau}{\sigma}>C_\tau\sqrt{D \log D}$, we choose $\xi = 2\sqrt{\log D/D}$ and we have

\begin{align*}
    \norm{(I)} 
&\leq \frac{2c_1 \alpha(\wtilde D+1)}{C_\tau D} + \frac{c_2 \alpha \sqrt{\wtilde D+1}( 1 + 4\alpha^2)^{\wtilde D} }
{C_\tau\sqrt{D \log D}}\frac{2}{\xi}e^{-(\wtilde D - 2 )\xi^2/2}
\\
&\leq \alpha\left(\frac{2c_1 }{C_\tau} + \frac{c_1 \sqrt{\wtilde D+1}( 1 + 4\alpha^2)^{\wtilde D} } 
{C_\tau\sqrt{D\log D }}\frac{4\sqrt{D}}{\sqrt{\log D}}e^{-\log D}\right)
\\
&\leq \alpha\left(\frac{2c_1 }{C_\tau} + \frac{2c_1 \sqrt{D}( 1 + 4\alpha^2)^{\wtilde D} }
{C_\tau D\log D }\right)
,\end{align*}
where the second inequality is true since  $(\wtilde D-2)/D \geq 1/2$.
Since $\alpha \leq  \sqrt{1/D} $, and we also have that $M>C_\tau\sqrt{D \log D}$ we have that 
$( 1 + 4\alpha^2)^{\wtilde D}$ is bounded for any $D$. Thus, we have that for $C_\tau$ large enough, 
\begin{align}
\norm{(I)} 
&\leq \frac{\varepsilon}{2}\alpha
\end{align}
for any $D$.


Next we bound $\|(II)\|$ from \eqref{eq:zDftilde}:
\begin{align*}
\frac{\wtilde D\int\limits_{\mathbb{S}_{\wtilde D-1}}z g(x,\theta)^{\wtilde D+1} d\theta \int\limits_{\mathbb{S}_{\wtilde D-1}} g(x,\theta)^{\wtilde D-1}\nabla_x g^T d\theta}
