&\leq  \frac{\xi\wtilde Dc_1 \sigma\alpha}{\tau} + \frac{\wtilde Dc_1 \sigma^2\alpha ( 1 + 4\alpha^2)^{\wtilde D+1}\int\limits_{\Omega_2}  d\theta }
